    let session = Arc::new(MemorySession::new());
    // Run 1: noop turn, inject "news", then pay defers.
    let model = RecordingModel::with_scripts(vec![noop_turn("c0"), pay_turn(&["call_1"])]);
    let pay = PayTool::new();
    let agent = two_tool_agent(Arc::clone(&model), &pay);
    let cp = Script::new(vec![CheckpointDecision::Inject(vec![ContentPart::Text { text: "news".into() }])]);
    let r1 = run(&agent, ctx(session.clone(), true).with_turn_checkpoint(cp.clone()), user("go")).await.expect("run1");
    assert!(matches!(r1.stop_reason, StopReason::Deferred { .. }), "{:?}", r1.stop_reason);
    assert_eq!(cp.seen.lock().unwrap().len(), 1, "no call at the deferred boundary");
    let reqs = model.requests();
    assert_eq!(reqs.len(), 2);
    assert_tool_calls_paired(&reqs[1].messages);
    let ls = labels(&session).await;
    println!("run1 log: {ls:?}");
    assert!(ls.contains(&"user_message(news)".to_owned()));
    assert_eq!(open_ids(&session).await.len(), 1);

    // Run 2: resume (approved) with a checkpoint that stops at the first boundary.
    let model2 = RecordingModel::with_scripts(vec![noop_turn("c2"), text_turn("never")]);
    let agent2 = two_tool_agent(Arc::clone(&model2), &pay);
    let cp2 = Script::new(vec![CheckpointDecision::Stop { reason: "halt".into() }]);
    let input = resolve_all(&session, ToolResolution::Approved).await;
    let r2 = run(&agent2, ctx(session.clone(), true).with_turn_checkpoint(cp2.clone()), input).await.expect("resume");
    assert_eq!(r2.stop_reason, StopReason::Stopped { reason: "halt".into() });
    assert_eq!(pay.calls().len(), 1, "pay runs once");
    let seen = cp2.seen.lock().unwrap().clone();
    assert_eq!(seen.len(), 1, "checkpoint not called at the resume step: {seen:?}");
    assert_eq!((seen[0].completed_turn, seen[0].next_turn), (0, 1));
    let reqs2 = model2.requests();
    assert_eq!(reqs2.len(), 1);
    assert_tool_calls_paired(&reqs2[0].messages);
    let ls2 = labels(&session).await;
    println!("run2 log: {ls2:?}");
    assert!(open_ids(&session).await.is_empty());

    // Run 3: a plain run on the stored session is valid.
    let model3 = RecordingModel::with_scripts(vec![text_turn("final")]);
    let agent3 = two_tool_agent(Arc::clone(&model3), &pay);
    let r3 = run(&agent3, ctx(session.clone(), true), user("again")).await.expect("run3");
    assert_eq!(r3.stop_reason, StopReason::Completed);
    assert_tool_calls_paired(&model3.requests()[0].messages);
}

