    let cp = Script::new(vec![CheckpointDecision::Inject(vec![ContentPart::Text { text: "news".into() }])]);
    let r1 = run(&parent, ctx(session.clone(), true).with_turn_checkpoint(cp.clone()), user("go")).await.expect("run1");
