    // The calls that wait for a result, in call order.
    let mut outstanding: Vec<&str> = Vec::new();
    for item in messages {
        match item {
            Item::ToolCall { call_id, .. } => {
                assert!(
                    !outstanding.contains(&call_id.as_str()),
                    "call {call_id} repeats while it waits for a result: {messages:?}"
                );
                outstanding.push(call_id);
            }
            Item::ToolResult { call_id, .. } => {
                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
                    panic!("result {call_id} has no open earlier call: {messages:?}");
                };
                // Each result closes one call.
                outstanding.remove(p);
            }
            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
                assert!(
                    outstanding.is_empty(),
                    "tool calls {outstanding:?} are not paired: {messages:?}"
                );
            }
            _ => {}
        }
    }
    assert!(
        outstanding.is_empty(),
        "tool calls {outstanding:?} are not paired: {messages:?}"
    );
}

/// The last three items of `messages` are the `pay` call `call_id`, its
/// result and the user message `"next"`.
fn assert_ends_with_result_then_next(messages: &[Item], call_id: &str) {
    let n = messages.len();
    assert!(n >= 3, "{messages:?}");
    assert!(
        matches!(&messages[n - 3], Item::ToolCall { call_id: id, name, .. }
            if id == call_id && name == "pay"),
        "{messages:?}"
    );
    assert!(
        matches!(&messages[n - 2], Item::ToolResult { call_id: id, .. } if id == call_id),
        "{messages:?}"
    );
    assert!(
        matches!(&messages[n - 1], Item::UserMessage { content } if text_of(content) == "next"),
        "{messages:?}"
    );
}


// ── Review probes: checkpoint x deferral ─────────────────────────────────────
use paigasus_helikon_core::{CheckpointDecision, TurnBoundary, TurnCheckpoint};

struct NoopTool {
    schema: serde_json::Value,
}
#[async_trait]
impl Tool<()> for NoopTool {
    fn name(&self) -> &str { "noop" }
    fn description(&self) -> &str { "ok" }
    fn schema(&self) -> &serde_json::Value { &self.schema }
    async fn invoke(&self, _c: &ToolContext<()>, _a: serde_json::Value) -> Result<ToolOutput, ToolError> {
        Ok(ToolOutput::new(serde_json::json!({"ok": true})))
    }
}

struct Script {
    d: Mutex<std::collections::VecDeque<CheckpointDecision>>,
    seen: Mutex<Vec<TurnBoundary>>,
}
impl Script {
    fn new(d: Vec<CheckpointDecision>) -> Arc<Self> {
        Arc::new(Self { d: Mutex::new(d.into()), seen: Mutex::new(Vec::new()) })
    }
}
#[async_trait]
impl TurnCheckpoint<()> for Script {
    async fn at_boundary(&self, _: &RunContext<()>, b: &TurnBoundary) -> CheckpointDecision {
        self.seen.lock().unwrap().push(b.clone());
        self.d.lock().unwrap().pop_front().unwrap_or(CheckpointDecision::Continue)
    }
}

fn noop_turn(id: &str) -> Vec<ModelEvent> {
    vec![
        ModelEvent::ToolCallDelta { call_id: id.into(), name: Some("noop".into()), args_delta: "{}".into() },
        ModelEvent::Finish { reason: FinishReason::ToolCalls },
    ]
}

fn two_tool_agent(model: Arc<RecordingModel>, pay: &Arc<PayTool>) -> LlmAgent<(), RecordingModel> {
    LlmAgent::builder::<()>()
        .name("root")
        .shared_model(model)
        .shared_tool(Arc::clone(pay) as Arc<dyn Tool<()>>)
        .shared_tool(Arc::new(NoopTool { schema: serde_json::json!({"type":"object"}) }) as Arc<dyn Tool<()>>)
        .build()
}

#[tokio::test]
async fn review_inject_then_defer_then_resume_then_stop() {
    let session = Arc::new(MemorySession::new());
    // Run 1: noop turn, inject "news", then pay defers.
    let model = RecordingModel::with_scripts(vec![noop_turn("c0"), pay_turn(&["call_1"])]);
    let pay = PayTool::new();
    let agent = two_tool_agent(Arc::clone(&model), &pay);
    let cp = Script::new(vec![CheckpointDecision::Inject(vec![ContentPart::Text { text: "news".into() }])]);
    let r1 = run(&agent, ctx(session.clone(), true).with_turn_checkpoint(cp.clone()), user("go")).await.expect("run1");
    assert!(matches!(r1.stop_reason, StopReason::Deferred { .. }), "{:?}", r1.stop_reason);
    assert_eq!(cp.seen.lock().unwrap().len(), 1, "no call at the deferred boundary");
    let reqs = model.requests();
    assert_eq!(reqs.len(), 2);
    assert_tool_calls_paired(&reqs[1].messages);
    let ls = labels(&session).await;
    println!("run1 log: {ls:?}");
    assert!(ls.contains(&"user_message(news)".to_owned()));
    assert_eq!(open_ids(&session).await.len(), 1);

    // Run 2: resume (approved) with a checkpoint that stops at the first boundary.
    let model2 = RecordingModel::with_scripts(vec![noop_turn("c2"), text_turn("never")]);
    let agent2 = two_tool_agent(Arc::clone(&model2), &pay);
    let cp2 = Script::new(vec![CheckpointDecision::Stop { reason: "halt".into() }]);
    let input = resolve_all(&session, ToolResolution::Approved).await;
    let r2 = run(&agent2, ctx(session.clone(), true).with_turn_checkpoint(cp2.clone()), input).await.expect("resume");
    assert_eq!(r2.stop_reason, StopReason::Stopped { reason: "halt".into() });
    assert_eq!(pay.calls().len(), 1, "pay runs once");
    let seen = cp2.seen.lock().unwrap().clone();
    assert_eq!(seen.len(), 1, "checkpoint not called at the resume step: {seen:?}");
    assert_eq!((seen[0].completed_turn, seen[0].next_turn), (0, 1));
    let reqs2 = model2.requests();
    assert_eq!(reqs2.len(), 1);
    assert_tool_calls_paired(&reqs2[0].messages);
    let ls2 = labels(&session).await;
    println!("run2 log: {ls2:?}");
    assert!(open_ids(&session).await.is_empty());

    // Run 3: a plain run on the stored session is valid.
    let model3 = RecordingModel::with_scripts(vec![text_turn("final")]);
    let agent3 = two_tool_agent(Arc::clone(&model3), &pay);
    let r3 = run(&agent3, ctx(session.clone(), true), user("again")).await.expect("run3");
    assert_eq!(r3.stop_reason, StopReason::Completed);
    assert_tool_calls_paired(&model3.requests()[0].messages);
}

#[tokio::test]
async fn review_handoff_child_inject_then_defer_then_resume() {
    let session = Arc::new(MemorySession::new());
    let pay = PayTool::new();
    // Parent transfers to child; child does noop, injected "news", then pay defers.
    let child_model = RecordingModel::with_scripts(vec![noop_turn("k0"), pay_turn(&["call_9"])]);
    let child = two_tool_agent_named("child", Arc::clone(&child_model), &pay);
    let parent_model = RecordingModel::with_scripts(vec![transfer_turn("t0", "child")]);
    let parent = LlmAgent::builder::<()>()
        .name("root")
        .shared_model(Arc::clone(&parent_model))
        .handoff(child)
        .build();
    let cp = Script::new(vec![CheckpointDecision::Inject(vec![ContentPart::Text { text: "news".into() }])]);
    let r1 = run(&parent, ctx(session.clone(), true).with_turn_checkpoint(cp.clone()), user("go")).await.expect("run1");
    assert!(matches!(r1.stop_reason, StopReason::Deferred { .. }), "{:?}", r1.stop_reason);
    println!("h run1 log: {:?}", labels(&session).await);
    assert_tool_calls_paired(&child_model.requests()[1].messages);

    // Resume: the path routes to the child, which runs pay, then the model answers.
    let child_model2 = RecordingModel::with_scripts(vec![text_turn("done")]);
    let child2 = two_tool_agent_named("child", Arc::clone(&child_model2), &pay);
    let parent_model2 = RecordingModel::with_scripts(vec![]);
    let parent2 = LlmAgent::builder::<()>()
        .name("root")
        .shared_model(Arc::clone(&parent_model2))
        .handoff(child2)
        .build();
    let input = resolve_all(&session, ToolResolution::Approved).await;
    let r2 = run(&parent2, ctx(session.clone(), true).with_turn_checkpoint(Script::new(vec![])), input).await.expect("resume");
    assert_eq!(r2.stop_reason, StopReason::Completed, "{:?}", r2.stop_reason);
    let req = &child_model2.requests()[0].messages;
    println!("child resume request: {req:?}");
    assert_tool_calls_paired(req);
    assert!(req.iter().any(|i| matches!(i, Item::UserMessage { content } if text_of(content) == "news")),
        "the child's resumed view keeps the injected message");
}

fn two_tool_agent_named(name: &str, model: Arc<RecordingModel>, pay: &Arc<PayTool>) -> LlmAgent<(), RecordingModel> {
    LlmAgent::builder::<()>()
        .name(name)
        .shared_model(model)
        .shared_tool(Arc::clone(pay) as Arc<dyn Tool<()>>)
        .shared_tool(Arc::new(NoopTool { schema: serde_json::json!({"type":"object"}) }) as Arc<dyn Tool<()>>)
        .build()
}
